def handle(args, state, ds):
    page = ds.fetch_review_items(cursor=args.get("cursor"))
    return {
        "items": page["items"],
        "next_cursor": page["next_cursor"]
    }

def handle(args, state, ds):
    status = ds.sync_status()
    return {
        "drift_detected": status["drift"],
        "in_sync": not status["drift"]
    }
